import{_ as a,o as e,c as i,a2 as n}from"./chunks/framework.Ddyno5UB.js";const k=JSON.parse('{"title":"Processes, Daemons, and Services","description":"","frontmatter":{},"headers":[],"relativePath":"linux/processes-and-services.md","filePath":"linux/processes-and-services.md"}'),t={name:"linux/processes-and-services.md"};function l(o,s,r,p,h,d){return e(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="processes-daemons-and-services" tabindex="-1">Processes, Daemons, and Services <a class="header-anchor" href="#processes-daemons-and-services" aria-label="Permalink to &quot;Processes, Daemons, and Services&quot;">​</a></h1><p>Understanding how Linux executes and manages programs is essential for server administration and deployment.</p><h2 id="what-is-a-process" tabindex="-1">What is a Process? <a class="header-anchor" href="#what-is-a-process" aria-label="Permalink to &quot;What is a Process?&quot;">​</a></h2><p>A <strong>Process</strong> is a running instance of a program. When you execute a command like <code>ls</code> or start a database, the Linux kernel loads the program into memory and assigns it a unique integer called a <strong>Process ID (PID)</strong>.</p><p>Every process (except the very first one) has a parent process that started it, identified by the <strong>Parent Process ID (PPID)</strong>.</p><h3 id="foreground-vs-background" tabindex="-1">Foreground vs. Background <a class="header-anchor" href="#foreground-vs-background" aria-label="Permalink to &quot;Foreground vs. Background&quot;">​</a></h3><p>When you run a command in your terminal, it runs in the <strong>foreground</strong>. You cannot use that terminal again until the command finishes.</p><p>To run a process in the <strong>background</strong>, append an ampersand (<code>&amp;</code>) to the command:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run a long backup script in the background</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./backup.sh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;</span></span></code></pre></div><p>You can bring a background job back to the foreground using <code>fg</code>, or send a running foreground job to the background by pausing it with <code>Ctrl+Z</code> and typing <code>bg</code>.</p><h2 id="what-is-a-daemon" tabindex="-1">What is a Daemon? <a class="header-anchor" href="#what-is-a-daemon" aria-label="Permalink to &quot;What is a Daemon?&quot;">​</a></h2><p>A <strong>Daemon</strong> (pronounced <em>demon</em>) is a special type of background process. Daemons are processes that:</p><ol><li>Run continuously in the background.</li><li>Are not attached to any interactive terminal (they don&#39;t need user input).</li><li>Usually start automatically when the system boots.</li></ol><p>In Linux, daemon processes typically have names ending with the letter <code>d</code> (e.g., <code>sshd</code> for the SSH daemon, <code>httpd</code> for the Apache web daemon, <code>systemd</code> for the system daemon).</p><h2 id="services-and-systemd" tabindex="-1">Services and Systemd <a class="header-anchor" href="#services-and-systemd" aria-label="Permalink to &quot;Services and Systemd&quot;">​</a></h2><p>While a daemon is the actual running process, a <strong>Service</strong> is the configuration that tells the system <em>how</em> to manage that daemon.</p><p>Modern Linux systems use <strong>systemd</strong> as the init system (the very first process, PID 1). Systemd is responsible for starting, stopping, and restarting all other daemons.</p><h3 id="managing-services-with-systemctl" tabindex="-1">Managing Services with <code>systemctl</code> <a class="header-anchor" href="#managing-services-with-systemctl" aria-label="Permalink to &quot;Managing Services with \`systemctl\`&quot;">​</a></h3><p>You interact with systemd using the <code>systemctl</code> command.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check if the Nginx web server daemon is currently running</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Start the Nginx daemon</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Stop the Nginx daemon</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Tell systemd to automatically start Nginx when the server boots up</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span></span></code></pre></div><h3 id="systemd-unit-files" tabindex="-1">Systemd Unit Files <a class="header-anchor" href="#systemd-unit-files" aria-label="Permalink to &quot;Systemd Unit Files&quot;">​</a></h3><p>How does systemd know how to start Nginx? It reads a configuration file called a <strong>Unit File</strong>. These files are typically located in <code>/usr/lib/systemd/system/</code> (provided by the package manager) or <code>/etc/systemd/system/</code> (custom ones created by administrators).</p><p>A basic unit file (<code>/etc/systemd/system/my-app.service</code>) looks like this:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Unit]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=My Custom Python Application</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">After</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=network.target</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Service]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=simple</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">User</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=appuser</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ExecStart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=/usr/bin/python3 /opt/myapp/main.py</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Restart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=on-failure</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Install]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WantedBy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=multi-user.target</span></span></code></pre></div><p>If you create or modify a unit file, you must tell systemd to reload its configuration before you can start the service:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> daemon-reload</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span></span></code></pre></div>`,26)])])}const g=a(t,[["render",l]]);export{k as __pageData,g as default};
